package app.kivo.store;
import java.io.*;import java.nio.file.*;import java.util.*;
public class PublicGithubTest {
 static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{List<String> calls=new ArrayList<>();GithubClient c=new GithubClient(Files.createTempDirectory("kivo-public-").toFile(),()->1700000000000L,(path,token,etag)->{calls.add(path+"|"+(token.isEmpty()?"anonymous":"authenticated"));return new GithubClient.Reply(token.isEmpty()?200:401,token.isEmpty()?"{\"id\":40}":"{\"message\":\"Bad credentials\"}",new HashMap<>());},null);
 check(c.getPublic("repos/a/b/releases/assets/40","expired-test-token",0).getInt("id")==40,"Public APK metadata must recover after rejected session");check(calls.size()==2&&calls.get(0).endsWith("authenticated")&&calls.get(1).endsWith("anonymous"),"Exactly one bounded anonymous retry");check(c.publicSessionRejected("expired-test-token"),"Rejection can be cleared from the host session");c.getPublic("repos/a/b/releases/latest","expired-test-token",0);check(calls.size()==3&&calls.get(2).endsWith("anonymous"),"Do not keep resending rejected token");
 int before=calls.size();try{c.getPublic("user","expired-test-token",0);throw new AssertionError("Profile authentication must fail");}catch(GithubClient.Failure e){check(e.code==401,"Profile must preserve HTTP 401");}check(calls.size()==before+1,"Never anonymously retry account profile");check(!GithubClient.publicRead("user")&&!GithubClient.publicRead("user/repos")&&!GithubClient.publicRead("repos/a/b/actions/secrets"),"Restricted endpoints are not public fallbacks");
 check(GithubClient.publicRead("repos/a/b/releases/assets/40")&&GithubClient.publicRead("repos/a/b/releases/latest")&&GithubClient.publicRead("repos/a/b/issues/12/comments?per_page=100&page=1"),"Bounded known read endpoints supported");
 GithubClient denied=new GithubClient(Files.createTempDirectory("kivo-forbidden-").toFile(),()->1700000000000L,(path,token,etag)->new GithubClient.Reply(403,"Forbidden",Collections.singletonMap("X-RateLimit-Remaining","10")),null);try{denied.getPublic("repos/a/b/releases/latest","test-token",0);throw new AssertionError("Forbidden must remain forbidden");}catch(GithubClient.Failure e){check(e.code==403&&!denied.publicSessionRejected("test-token"),"No auth fallback for 403 or quotas");}
 System.out.println("PASS: public APK metadata survives expired session; profile stays authenticated; no repeated invalid-token loop or 403 fallback.");}
}
